// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1e30);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        assertEq(c.getBalance(actor), amount);

        uint256 contractBalBefore = address(c).balance;

        vm.prank(actor);
        c.withdrawBalance();

        // General rule: withdrawing zeroes the user's balance and pays out the
        // stored balance, so the contract's ether balance must drop by exactly
        // the amount that was deposited. The buggy version sends 0 ether, so
        // the contract balance does not decrease.
        assertTrue(
            address(c).balance == contractBalBefore - amount && c.getBalance(actor) == 0
        );
    }
}
